# Secretos del servicio deployer-reverb: VARIABLE=nombre-en-Secret-Manager. Son los mismos secretos
# que usa la API (secrets.map), así las REVERB_APP_* nunca se desincronizan.

APP_KEY=deployer-api-app-key
REVERB_APP_ID=deployer-reverb-app-id
REVERB_APP_KEY=deployer-reverb-app-key
REVERB_APP_SECRET=deployer-reverb-app-secret
